import './control.css';
import './leave-dialog.css';

interface LeaveDialogProps {
  action: (() => void) | null;
  close(): void;
}

export function LeaveDialog({ action, close }: LeaveDialogProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const keep = useRef<HTMLButtonElement>(null);
