import { freshBoardCode } from '../session/fresh-board.ts';
import { browserStore } from '../session/use-saved-preferences.ts';
import { createTournament, finishTurn, matchPlayers, matchSizes, matchWinner, nameProblem, nextTurn, TournamentPhase } from './rules.ts';
import { decodeTournament } from './format.ts';
import { readTournaments, retainTournament, writeTournaments } from './storage.ts';
import type { GameState } from '../game.ts';
import type { Tournament } from './rules.ts';

export function useTournament(announce: (text: string) => void, confirm: (action: () => void) => void) {
  const [store] = useState(browserStore);
  const [history, setHistory] = useState(() => readTournaments(store));
  const [players, setPlayers] = useState<readonly string[]>(['', '', '', '']);
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [restored, setRestored] = useState<GameState | null>(null);
  const [generation, setGeneration] = useState(0);
  const [notice, setNotice] = useState('');

  function notify(text: string): void { setNotice(text); announce(text); }
  function save(completed: Tournament): void {
    const items = retainTournament(history.items, completed);
    const available = writeTournaments(store, items);
    setHistory({ items, available });
  }
  function showTurn(next: Tournament): void {
    const match = next.matches[next.matchIndex];
    const player = matchPlayers(next, next.matchIndex)[match?.results.length ?? 0];
    setTournament(next);
    setNotice('');
    announce(`Now playing: ${player == null ? '' : next.players[player]}`);
  }
  function start(): void {
    const problem = nameProblem(players);
    if (problem) { notify(problem); return; }
    const codes: string[] = [];
    for (const size of matchSizes(players.length)) {
      let code = freshBoardCode(size);
      while (codes.includes(code)) code = freshBoardCode(size);
      codes.push(code);
    }
    setRestored(null);
    setGeneration(generation + 1);
    showTurn(createTournament(players, codes));
  }
  function begin(): void {
    if (!tournament || tournament.phase !== TournamentPhase.ready) return;
    showTurn({ ...tournament, phase: TournamentPhase.playing });
  }
  function finish(game: GameState, feedback: string): void {
    if (!tournament) return;
    const next = finishTurn(tournament, game);
    if (next === tournament) return;
    setRestored(null);
    setTournament(next);
    const winner = matchWinner(next, next.matchIndex);
    const outcome = next.phase === TournamentPhase.complete ? `Champion: ${winner == null ? '' : next.players[winner]}`
      : winner == null ? 'Select Next turn.' : `Winner: ${next.players[winner]}. Select Next match.`;
    announce(`${feedback} ${outcome}`);
    if (next.phase === TournamentPhase.complete) save(next);
  }
  function advance(): void {
    if (tournament) showTurn(nextTurn(tournament));
    setGeneration(generation + 1);
  }
  function load(text: string): void {
    const result = decodeTournament(text);
    if (!result.data) { notify(result.error); return; }
    const data = result.data;
    const apply = () => {
      setTournament(data.tournament);
      setPlayers(data.players);
      setRestored(data.game);
      setGeneration(generation + 1);
      notify(data.game ? 'Loaded tournament. Select Start turn to continue.' : 'Loaded tournament.');
      if (data.tournament?.phase === TournamentPhase.complete) save(data.tournament);
    };
    if (tournament && tournament.phase !== TournamentPhase.complete) confirm(apply);
    else apply();
  }
  function reset(): void {
    setTournament(null);
    setRestored(null);
    setNotice('');
    setGeneration(generation + 1);
  }
  return { players, setPlayers, tournament, restored, generation, notice, history, start, begin, finish, advance, load, reset };
}

/work/src/game/tournament/Setup.tsx.content:
interface SetupProps {
  players: readonly string[];
  change(players: readonly string[]): void;
  start(): void;
  notice: string;
}

export function Setup({ players, change, start, notice }: SetupProps) {
  return (
    <form className="tournament-setup" onSubmit={(event) => { event.preventDefault(); start(); }}>
      <div className="tournament-field">
        <label htmlFor="player-count">Players</label>
        <select id="player-count" className="control" value={players.length} onChange={(event) => {
          const count = Number(event.currentTarget.value);
          change(Array.from({ length: count }, (_, index) => players[index] ?? ''));
        }}>
          <option value="4">4</option><option value="8">8</option>
        </select>
      </div>
      <div className="tournament-names">
        {players.map((name, index) => (
          <div className="tournament-field" key={index}>
            <label htmlFor={`player-${index + 1}`}>Player {index + 1}</label>
            <input id={`player-${index + 1}`} className="control" value={name} aria-describedby="tournament-notice"
              onChange={(event) => change(players.map((item, position) => position === index ? event.currentTarget.value : item))} />
          </div>
        ))}
      </div>
      <p className="help">Use 2 to 20 characters per name. Each name must be different.</p>
      <p id="tournament-notice">{notice}</p>
      <button className="control" type="submit">Start tournament</button>
    </form>
  );
}

/work/src/game/tournament/Exchange.tsx.content:
import { TOURNAMENT_MAX_BYTES } from './format.ts';

interface ExchangeProps {
  draft: string;
  change(text: string): void;
  exportTournament(): void;
  load(): void;
  notice: string;
}
export function Exchange({ draft, change, exportTournament, load, notice }: ExchangeProps) {
  return (
    <section className="tournament-exchange" aria-label="Tournament sharing">
      <label htmlFor="tournament-json">Tournament JSON</label>
      <textarea id="tournament-json" className="control" value={draft} rows={6} spellCheck={false}
        maxLength={TOURNAMENT_MAX_BYTES} onChange={(event) => change(event.currentTarget.value)} />
      <div className="tournament-actions">
        <button className="control" onClick={exportTournament}>Export tournament</button>
        <button className="control" aria-describedby="tournament-load-notice" onClick={load}>Load tournament</button>
      </div>
      <p id="tournament-load-notice">{notice}</p>
    </section>
  );
}

/work/src/game/tournament/Bracket.tsx.content:
import { parseBoardCode } from '../deck.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { matchPlayers, matchWinner, roundName } from './rules.ts';
import type { Tournament } from './rules.ts';

export function Bracket({ tournament }: { tournament: Tournament }) {
  return (
    <div className="tournament-table" tabIndex={0} role="region" aria-label="Tournament bracket">
      <table>
        <caption>Bracket</caption>
        <thead><tr>{['Match', 'Round', 'Player', 'Moves', 'Time', 'Winner'].map((label) => <th scope="col" key={label}>{label}</th>)}</tr></thead>
        <tbody>
          {tournament.matches.flatMap((match, index) => {
            const winner = matchWinner(tournament, index);
            return matchPlayers(tournament, index).map((player, turn) => {
              const result = match.results[turn];
              return (
                <tr key={`${index}-${turn}`}>
                  <td>{index + 1}</td><td>{roundName(parseBoardCode(match.boardCode)?.size ?? 8)}</td>
                  <td>{player == null ? 'To be decided' : tournament.players[player]}</td>
                  <td>{result?.moves ?? '—'}</td><td>{result ? formatElapsed(result.elapsedMs) : '—'}</td>
                  <td>{winner == null ? '—' : tournament.players[winner]}</td>
                </tr>
              );
            });
          })}
        </tbody>
      </table>
    </div>
  );
}

